# ---------------------------------------------------------------------------

make_history <- function(
  years    = 2019:2023,
  n_teams  = 10,
  cats     = c("HR", "R", "RBI", "SB"),
  seed     = 42
) {
  set.seed(seed)
  team_ids <- paste0("T", seq_len(n_teams))
  rows <- lapply(years, function(y) {
    df <- data.frame(
      year    = y,
      team_id = team_ids,
      stringsAsFactors = FALSE
    )
    for (cat in cats) {
      params <- switch(cat,
        HR  = list(mean = 200, sd = 30),
        R   = list(mean = 700, sd = 60),
        RBI = list(mean = 650, sd = 55),
        SB  = list(mean = 100, sd = 25),
        ERA = list(mean = 3.8,  sd = 0.4),
        WHIP= list(mean = 1.25, sd = 0.10),
        list(mean = 100, sd = 20)
      )
      df[[cat]] <- round(rnorm(n_teams, params$mean, params$sd), 4)
    }
    df
  })
  ts <- do.call(rbind, rows)
  list(team_season = ts)
}

make_exact_history <- function(n_teams = 10, n_years = 3, slope = 0.05) {
  years <- seq(2020, 2020 + n_years - 1)
  rows <- lapply(seq_along(years), function(i) {
    y <- years[i]
    totals <- seq(100, 100 + (n_teams - 1) * (1 / slope), length.out = n_teams)
    data.frame(
      year    = y,
      team_id = paste0("T", seq_len(n_teams)),
      HR      = totals
    )
  })
  list(team_season = do.call(rbind, rows))
}

