# T-01: OLS basic — 3 teams x 2 years, exact computation
test_that("T-01: OLS 3-teams x 2-years exact computation", {
  ts <- data.frame(
    year    = c(2022, 2022, 2022, 2023, 2023, 2023),
    team_id = c("A", "B", "C", "A", "B", "C"),
    HR      = c(150, 180, 210, 170, 195, 220)
  )
  h <- list(team_season = ts)
  result <- sgp_denominators(
    h,
    scoring_categories = "HR",
    n_teams            = 3L,
    years              = "all",
    weights            = flat(),
    method             = "ols",
    exclude_years      = integer(0)
  )

  # Return class
  expect_s3_class(result, "sgp_denominators")
  expect_true(inherits(result, "list"))

  # Primary denominator
  expect_equal(result$denominators[["HR"]], 1 / mean(c(1/30, 1/25)),
               tolerance = 1e-4)
  # Exact value cross-check
  expect_equal(result$denominators[["HR"]], 27.27, tolerance = 0.02)

  # year_diagnostics structure
  expect_equal(nrow(result$year_diagnostics), 2)
  expect_equal(sort(result$year_diagnostics$year), c(2022L, 2023L))
  expect_equal(result$year_diagnostics$category, c("HR", "HR"))
  expect_equal(result$year_diagnostics$n_teams, c(3L, 3L))
  expect_equal(result$year_diagnostics$slope[result$year_diagnostics$year == 2022],
               1/30, tolerance = 1e-5)
  expect_equal(result$year_diagnostics$slope[result$year_diagnostics$year == 2023],
               1/25, tolerance = 1e-5)
  expect_true(all(abs(result$year_diagnostics$r_squared - 1.0) < 1e-10))

  # Flat weights: normalized and equal
  expect_equal(result$year_diagnostics$weight, c(0.5, 0.5), tolerance = 1e-10)
})

# T-02: OLS basic — 10 teams x 5 years, realistic data
test_that("T-02: OLS 10-teams x 5-years realistic multi-category data", {
  h <- make_history(years = 2019:2023, n_teams = 10,
                    cats = c("HR", "R", "RBI", "SB"), seed = 42)
  result <- sgp_denominators(
    h,
    scoring_categories = c("HR", "R", "RBI", "SB"),
    n_teams            = 10L,
    years              = "all",
    weights            = exp_decay(0.9),
    method             = "ols",
    exclude_years      = integer(0)
  )

  expect_s3_class(result, "sgp_denominators")
  expect_equal(length(result$denominators), 4)
  expect_equal(sort(names(result$denominators)), sort(c("HR", "R", "RBI", "SB")))
  expect_true(all(is.finite(result$denominators)))
  expect_true(all(result$denominators > 0))
  expect_equal(nrow(result$year_diagnostics), 20)  # 5 years x 4 cats
  expect_true(all(result$year_diagnostics$r_squared > 0.5))
  expect_equal(result$meta$method, "ols")
  expect_equal(result$meta$rate_conversion, "blended_pool")
})

# T-03: Denominator inversion correct for known slope
test_that("T-03: Denominator inversion matches lm() slope exactly", {
  totals <- seq(100, 325, by = 25)   # 10 values
  ts <- data.frame(
    year    = rep(2022L, 10),
    team_id = paste0("T", 1:10),
    HR      = totals
  )
  h <- list(team_season = ts)
  result <- sgp_denominators(
    h,
    scoring_categories = "HR",
    n_teams            = 10L,
    exclude_years      = integer(0),
    method             = "ols",
    weights            = flat()
  )

  fit <- lm(1:10 ~ totals)
  expected_slope <- coef(fit)[["totals"]]
  expected_denom <- 1 / abs(expected_slope)

  expect_equal(result$denominators[["HR"]], expected_denom, tolerance = 1e-8)
})

