# T-11: years = after(2022) restricts calibration to 2023+
test_that("T-11: after(2022) restricts year window to 2023+", {
  h <- make_history(years = 2019:2024, seed = 10)
  result_all <- suppressWarnings(suppressMessages(
    sgp_denominators(h, scoring_categories="HR",
                     years = "all", exclude_years = integer(0))
  ))
  result_after <- suppressMessages(
    sgp_denominators(h, scoring_categories="HR",
                     years = after(2022), exclude_years = integer(0))
  )

  expect_true(max(result_all$meta$years_used) >= 2024)
  expect_true(min(result_after$meta$years_used) >= 2023)
  expect_true(all(result_after$year_diagnostics$year >= 2023))
})

# T-12: between(2020, 2022) is inclusive on both ends
test_that("T-12: between() is inclusive on both endpoints", {
  h <- make_history(years = 2018:2024, seed = 11)
  result <- suppressMessages(
    sgp_denominators(h, scoring_categories="HR",
                     years = between(2020, 2022), exclude_years = integer(0))
  )
  expect_equal(sort(unique(result$year_diagnostics$year)), c(2020L, 2021L, 2022L))
})

# T-13: last(3) returns only the 3 most recent years
test_that("T-13: last(3) uses only the 3 most recent years", {
  h <- make_history(years = 2018:2024, seed = 12)
  result <- suppressMessages(
    sgp_denominators(h, scoring_categories="HR",
                     years = last(3), exclude_years = integer(0))
  )
  expect_equal(sort(unique(result$year_diagnostics$year)), c(2022L, 2023L, 2024L))
})

# T-14: exclude_years = 2020L removes 2020 from all categories
test_that("T-14: exclude_years removes 2020 from diagnostics and meta", {
  h <- make_history(years = 2018:2023, seed = 13)
  result <- suppressMessages(
    sgp_denominators(h, scoring_categories="HR",
                     years = "all", exclude_years = 2020L)
  )
  expect_false(2020L %in% result$year_diagnostics$year)
  expect_false(2020L %in% result$meta$years_used)
})

# T-15: exp_decay(0.9) produces higher weight for more recent years
test_that("T-15: exp_decay(0.9) weights are monotonically increasing with year", {
  h <- make_history(years = 2018:2023, seed = 14)
  result <- suppressMessages(
    sgp_denominators(h, scoring_categories="HR",
                     years = "all", exclude_years = integer(0),
                     weights = exp_decay(0.9))
  )
  diag <- result$year_diagnostics[result$year_diagnostics$category == "HR", ]
  diag <- diag[order(diag$year), ]
  expect_true(all(diff(diag$weight) > 0))
})

# T-16: Per-category override via category_spec
test_that("T-16: category_spec per-category override applies correctly", {
  h <- make_history(years = 2018:2024, cats = c("HR", "SB"), seed = 15)
  result <- suppressWarnings(suppressMessages(
    sgp_denominators(
      h,
      scoring_categories = c("HR", "SB"),
      years = "all",
      exclude_years = integer(0),
      category_spec = cal_spec(
        SB = cal(years = after(2022))
      )
    )
  ))
  # SB should only use 2023, 2024
  sb_years <- result$year_diagnostics$year[result$year_diagnostics$category == "SB"]
  expect_true(all(sb_years >= 2023))

  # HR should use all years
  hr_years <- result$year_diagnostics$year[result$year_diagnostics$category == "HR"]
  expect_equal(sort(hr_years), 2018:2024)
})

