# T-17: method = "gap" produces range/(n-1) denominator
test_that("T-17: gap method = range / (n-1)", {
  totals <- c(100, 130, 170, 180, 220)
  ts <- data.frame(year=2022L, team_id=paste0("T",1:5), HR=totals)
  h <- list(team_season=ts)

  result <- sgp_denominators(h, scoring_categories="HR", n_teams=5L,
                              method="gap", exclude_years=integer(0), weights=flat())

  expected_denom <- diff(range(totals)) / (5 - 1)  # (220-100)/4 = 30
  expect_equal(result$denominators[["HR"]], expected_denom, tolerance=1e-8)
})

# T-18: method = "trimmed_gap" trims 10% from each end
test_that("T-18: trimmed_gap trims 1 gap from each end with n=20", {
  set.seed(101)
  ts20 <- data.frame(
    year    = rep(2022L, 20),
    team_id = paste0("T", 1:20),
    HR      = sort(runif(20, 100, 300))
  )
  h20 <- list(team_season=ts20)

  result_trim <- sgp_denominators(h20, "HR", n_teams=20L, method="trimmed_gap",
                                   exclude_years=integer(0), weights=flat())

  gaps <- diff(sort(ts20$HR))
  gaps_trimmed <- gaps[2:(length(gaps)-1)]  # k=1 from each end
  expected_trim <- mean(gaps_trimmed)

  expect_equal(result_trim$denominators[["HR"]], expected_trim, tolerance=1e-6)
})

# T-19: method = "sd" uses expected_range_normal() scaling
test_that("T-19: sd method uses expected_range_normal scaling", {
  set.seed(100)
  n_teams <- 12
  totals <- rnorm(n_teams, mean=200, sd=30)
  ts <- data.frame(year=2022L, team_id=paste0("T",1:n_teams), HR=totals)
  h <- list(team_season=ts)

  result <- sgp_denominators(h, "HR", n_teams=n_teams, method="sd",
                              exclude_years=integer(0), weights=flat())

  E_Rn <- 3.2587  # known anchor for n=12
  expected_denom <- sd(totals) * (n_teams - 1) / E_Rn
  expect_equal(result$denominators[["HR"]], expected_denom, tolerance=0.01)
})

# T-20: expected_range_normal() anchor values
test_that("T-20: expected_range_normal() anchors match known values", {
  # From test-spec.md §15: corrected n=15 anchor is 3.4718 (not 3.5241)
  expect_equal(expected_range_normal(10), 3.0776, tolerance=1e-3)
  expect_equal(expected_range_normal(12), 3.2587, tolerance=1e-3)
  expect_equal(expected_range_normal(15), 3.4718, tolerance=1e-3)
})

