# T-21: Zero-variance category (all teams tied in a year)
test_that("T-21: Zero-variance year emits warning and NA slope; denominator from valid year", {
  ts <- rbind(
    data.frame(year=2022L, team_id=c("A","B","C"), HR=c(150, 180, 210)),
    data.frame(year=2023L, team_id=c("A","B","C"), HR=c(150, 150, 150))
  )
  h <- list(team_season=ts)

  expect_warning(
    result <- sgp_denominators(h, "HR", n_teams=3L, exclude_years=integer(0)),
    class = "rotostats_warning_zero_variance_category"
  )

  diag_2023 <- result$year_diagnostics[result$year_diagnostics$year == 2023, ]
  expect_true(is.na(diag_2023$slope))

  expect_true(is.finite(result$denominators[["HR"]]))
  expect_equal(result$denominators[["HR"]], 1 / (1/30), tolerance=1e-5)
})

