# T-27: SB structural break warning (flat weights, pre+post 2023)
test_that("T-27: SB structural break warning fires for flat weights spanning 2022/2023", {
  h <- make_history(years = 2019:2024, cats=c("SB"), seed = 21)

  # Flat weights spanning break -> warning
  expect_warning(
    sgp_denominators(h, scoring_categories="SB",
                     years="all", weights=flat(), exclude_years=integer(0)),
    class = "rotostats_warning_structural_break_flat_weights"
  )

  # exp_decay weights -> no structural break warning
  expect_no_warning(
    suppressWarnings(
      sgp_denominators(h, scoring_categories="SB",
                       years="all", weights=exp_decay(0.7), exclude_years=integer(0))
    ),
    class = "rotostats_warning_structural_break_flat_weights"
  )

  # Window restricted to post-2022 -> no structural break warning
  expect_no_warning(
    suppressWarnings(
      sgp_denominators(h, scoring_categories="SB",
                       years=after(2022), weights=flat(), exclude_years=integer(0))
    ),
    class = "rotostats_warning_structural_break_flat_weights"
  )
})

