# T-45: n_bootstrap = 200 -> $bootstrap_ci is data.frame with correct schema
test_that("T-45: n_bootstrap=200 produces bootstrap_ci data.frame with correct schema", {
  h <- make_history(cats=c("HR","SB"), seed=1)
  set.seed(99)
  result <- suppressMessages(
    sgp_denominators(h, scoring_categories=c("HR","SB"),
                     n_bootstrap=200L, ci_level=0.95,
                     exclude_years=integer(0))
  )

  expect_true(is.data.frame(result$bootstrap_ci))
  expect_named(result$bootstrap_ci, c("category","ci_lower","ci_upper","ci_level","n_bootstrap"))
  expect_equal(nrow(result$bootstrap_ci), 2)
