  expect_equal(result$bootstrap_ci$ci_level, c(0.95, 0.95))
  expect_equal(result$bootstrap_ci$n_bootstrap, c(200L, 200L))
  # CIs must straddle the point estimate
  expect_true(all(result$bootstrap_ci$ci_lower < result$denominators[result$bootstrap_ci$category]))
  expect_true(all(result$bootstrap_ci$ci_upper > result$denominators[result$bootstrap_ci$category]))
})

