  )
  h <- list(team_season = ts)
  expect_no_warning(
    result <- sgp_denominators(h, "ERA", n_teams = 5L, exclude_years = integer(0)),
    class = "rotostats_warning_unexpected_slope_sign"
  )
  diag <- result$year_diagnostics
  expect_true(diag$slope < 0)
